<?php
namespace App\Http\Controllers;
use App\Models\Pengaduan; use Illuminate\Http\Request; use Illuminate\Support\Facades\Http;
class PengaduanController extends Controller { public function create(){ return view('pengaduan.create'); } public function store(Request $request){ $request->validate(['nama'=>'required|string|max:150','email'=>'nullable|email|max:150','telepon'=>'nullable|string|max:30','kategori'=>'required|string|max:80','judul'=>'required|string|max:200','isi'=>'required|string|max:5000','cf-turnstile-response'=>'required']); $v=Http::asForm()->timeout(8)->post('https://challenges.cloudflare.com/turnstile/v0/siteverify',['secret'=>config('services.cloudflare.turnstile.secret_key'),'response'=>$request->input('cf-turnstile-response'),'remoteip'=>$request->ip()]); if(!$v->successful()||!$v->json('success')) return back()->withInput()->withErrors(['cf-turnstile-response'=>'Verifikasi keamanan gagal.']); Pengaduan::create($request->only(['nama','email','telepon','kategori','judul','isi'])); return back()->with('success','Pengaduan berhasil dikirim dan menunggu verifikasi admin.'); } }
